import { attrs, defaults, isWeb, nonWebGroups, q, list, unique, wholeLabelWildcard } from './util.js';

const fqdns = (eps) => unique(eps.map((e) => wholeLabelWildcard(e.host))).sort();

function generate(endpoints, options = {}) {
  const o = defaults(options);
  const label = o.scope ? ` (${o.scope})` : '';
  const src = o.sourceAddress === 'any' ? '*' : o.sourceAddress;
  const out = [];

  out.push(`# Azure Firewall Policy rules for Azure Local endpoints${label}
# Generated by azure-local-endpoints. Review before applying.
# FQDNs in network rules require the DNS proxy to be enabled on the firewall policy.
terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = ">= 3.100"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "firewall_policy_id" {
  type        = string
  description = "Resource ID of the existing Azure Firewall Policy"
}

variable "source_addresses" {
  type        = list(string)
  default     = [${q(src)}]
  description = "Source addresses or ranges of the Azure Local nodes"
}

variable "rule_collection_priority" {
  type        = number
  default     = 1000
  description = "Priority of the rule collection group"
}
`);

  const appRules = [];
  const web = endpoints.filter(isWeb);
  for (const [type, port] of [['Https', 443], ['Http', 80]]) {
    const hosts = fqdns(web.filter((e) => e.ports.includes(port)));
    if (hosts.length) appRules.push({ type, port, hosts });
  }

  const netRules = nonWebGroups(endpoints).map((g) => ({ g, hosts: fqdns(g.endpoints) }));

  const blocks = [];
  if (appRules.length) {
    blocks.push(`  application_rule_collection {
${attrs(4, [['name', q(`${o.prefix}-web`)], ['priority', '1000'], ['action', '"Allow"']])}
${appRules.map((r) => `
    rule {
${attrs(6, [
      ['name', q(`${o.prefix}-allow-${r.type.toLowerCase()}`)],
      ['source_addresses', 'var.source_addresses'],
      ['destination_fqdns', list(r.hosts.map(q), 8)]
    ])}

      protocols {
        type = ${q(r.type)}
        port = ${r.port}
      }
    }`).join('\n')}
  }`);
  }
  if (netRules.length) {
    blocks.push(`  network_rule_collection {
${attrs(4, [['name', q(`${o.prefix}-other`)], ['priority', '1100'], ['action', '"Allow"']])}
${netRules.map(({ g, hosts }) => `
    rule {
${attrs(6, [
      ['name', q(`${o.prefix}-allow-${g.protocol}-${g.port}`)],
      ['protocols', `[${q(g.protocol.toUpperCase())}]`],
      ['source_addresses', 'var.source_addresses'],
      ['destination_fqdns', list(hosts.map(q), 8)],
      ['destination_ports', `[${q(g.port)}]`]
    ])}
    }`).join('\n')}
  }`);
  }

  out.push(`resource "azurerm_firewall_policy_rule_collection_group" "${o.prefix}" {
${attrs(2, [
    ['name', q(`${o.prefix}-azure-local`)],
    ['firewall_policy_id', 'var.firewall_policy_id'],
    ['priority', 'var.rule_collection_priority']
  ])}

${blocks.join('\n\n')}
}
`);
  return [{ filename: `${o.prefix}-azurefirewall.tf`, content: out.join('\n') }];
}

export default {
  id: 'azurefirewall',
  name: 'Azure Firewall',
  description: 'azurerm provider: application and network rule collections in a firewall policy rule collection group.',
  generate
};
